/*
 * Song sources. The game and scorer only consume this normalised shape:
 *   { id, title, artist, duration, leadIn, audioUrl,
 *     notes: [{t, d, midi, syl, line}],          // reference melody (seconds, MIDI note numbers)
 *     lines: [{t, end, words: [{t, d, text}]}] }  // timed lyrics; text ending in "-" joins the next syllable
 *
 * LocalSongSource reads songs/<id>/song.json (generated by tools/build-song.js).
 *
 * StingraySongSource talks to the local server (server/stingray.js implements Stingray Karaoke API v1:
 * X-API-KEY + /v1/login-device bearer token, /v1/songs/{id}?withPlayLink&withKml, KML lyrics, /v1/play-log).
 * The API key never reaches the TV. Stingray ships no pitch data, so the server derives notes[] from
 * the lead-vocal (C_MIX) minus instrumental (A_MIX) media; songs without a derivable melody have scorable:false.
 */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.KaraokeSongs = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';
  function getJson(url, cb) {
    var x = new XMLHttpRequest(); // XHR works for packaged files in Tizen widgets (fetch on file:// may not)
    x.open('GET', url); x.onload = function () {
      if (x.status && x.status !== 200) return cb(new Error('HTTP ' + x.status));
      try { cb(null, JSON.parse(x.responseText)); } catch (e) { cb(e); }
    };
    x.onerror = function () { cb(new Error('load failed: ' + url)); };
    x.send();
  }
  function LocalSongSource(base) { this.base = base || 'songs/'; }
  LocalSongSource.prototype.list = function () { return [{ id: 'twinkle', title: 'Twinkle, Twinkle, Little Star', artist: 'Traditional' }]; };
  LocalSongSource.prototype.load = function (id, cb) {
    var base = this.base + id + '/';
    getJson(base + 'song.json', function (err, s) {
      if (err) return cb(err);
      s.audioUrl = base + s.audio;
      if (s.guide) s.guideUrl = base + s.guide;
      cb(null, s);
    });
  };
  /** Stingray v1 via the local server (which holds the API key and derives the reference melody). */
  function StingraySongSource(server) { this.server = server; }
  StingraySongSource.prototype.status = function (cb) { getJson(this.server + '/api/stingray/status', cb); };
  StingraySongSource.prototype.search = function (q, cb) { getJson(this.server + '/api/stingray/search?q=' + encodeURIComponent(q), cb); };
  StingraySongSource.prototype.load = function (id, cb) { getJson(this.server + '/api/stingray/song?id=' + encodeURIComponent(id || ''), cb); };
  StingraySongSource.prototype.logPlay = function (id, seconds) {
    var x = new XMLHttpRequest(); x.open('POST', this.server + '/api/stingray/play-log'); x.setRequestHeader('Content-Type', 'application/json');
    x.send(JSON.stringify({ id: id, seconds: seconds }));
  };
  return { LocalSongSource: LocalSongSource, StingraySongSource: StingraySongSource, getJson: getJson };
});
